     "time": "09-08 12:27",
     "ts": 1788841626,
     "summary": "伊朗议会议长卡利巴夫9月7日警告说，如果美国打击伊朗石油和天然气资产，美国在海湾地区的能源资产将会遭到伊朗报复性打击。 卡利巴夫在社交媒体上发文称，海湾地区油气生产链“庞大、容易接近且暴露于风险之中”，美国在该地区的石油和天然气公司也面临同样风险。他警告说：“打击我们的资产，你们（美国）也会遭到打击。”（新华社）（文章来源：界面新闻）",
