     "time": "09-08 12:20",
     "ts": 1788841217,
     "summary": "古巴外交部长罗德里格斯9月7日称，美国对古巴实施的贸易禁运已造成“创纪录”的经济损失。罗德里格斯当天主持新闻发布会，发布关于2025年3月1日至2026年2月28日美国对古巴实施贸易禁运的报告。报告显示，这期间美对古巴贸易禁运造成的经济损失达80.833亿美元，创历史新高。 （文章来源：财联社）",
